SELECT stock_id, trade_date, foreign_buy_shares, foreign_sell_shares, foreign_net_shares, foreign_dealer_buy_shares, foreign_dealer_sell_shares, foreign_dealer_net_shares, trust_buy_shares, trust_sell_shares, trust_net_shares, dealer_net_shares, dealer_self_buy_shares, dealer_self_sell_shares, dealer_self_net_shares, dealer_hedge_buy_shares, dealer_hedge_sell_shares, dealer_hedge_net_shares, total_net_shares, source FROM stock_institutional_trade WHERE stock_id IN
#{id}
AND trade_date BETWEEN #{startDate} AND #{endDate} ORDER BY stock_id, trade_date ASC
